package com.hssa.common.validator; import com.hssa.common.annotation.ValidUUID; import com.hssa.common.util.UUIDUtils; import jakarta.validation.ConstraintValidator; import jakarta.validation.ConstraintValidatorContext; public class ValidUUIDValidator implements ConstraintValidator<ValidUUID, String> { @Override public boolean isValid(String value, ConstraintValidatorContext context) { if (value == null) return true; return UUIDUtils.isValid(value); } }
